/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to Order guides and add entry to Price Change tracking table for later processing
/// </summary>
using System.ComponentModel.Composition;

[Export(identifierStr(Dynamics.AX.Application.METPriceChangeEvent))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, OrderGuideDoNotSellTo))]
public class METPriceChangeEventDoNotSellTo extends METPriceChangeEventOrderGuide
{
}

Method.Source:
/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::OrderGuideDoNotSellTo;
}
